             */
        }

        [Fact]
        public void TransitionGuardNamesAsync()
        {
            var sm = new StateMachine<State, Trigger>(State.A);

            sm.Configure(State.A)
                .PermitIf(Trigger.X, State.B, Permit);
            sm.Configure(State.B)
