            sm.Configure(State.D)
                .PermitDynamicIfAsync(Trigger.X, () => Task.FromResult(NextState()), () => Permit(), UserDescription + "D-Permit");

            inf = sm.GetInfo();

            foreach (StateInfo stateInfo in inf.States)
            {
